// Valida evento vindo do BACKEND (HMAC + janela de tempo)
const crypto = require('crypto');
const h = $input.item.json.headers || {};
const ts = h['x-airflow-timestamp'];
const sig = h['x-airflow-signature'];
const body = JSON.stringify($input.item.json.body);
if (!ts || !sig) throw new Error('Assinatura ausente');
if (Math.abs(Date.now()/1000 - Number(ts)) > 300) throw new Error('Timestamp fora da janela');
const esperado = crypto.createHmac('sha256', $env.N8N_WEBHOOK_SECRET).update(ts + '.' + body).digest('hex');
if (esperado !== sig) throw new Error('Assinatura invalida');
return { json: $input.item.json.body };

// Roteia o evento para o workflow responsavel (WF-02..WF-12)
const rotas = {
  'proposal.created': 'wf-02-enviar-proposta',
  'proposal.countered': 'wf-04-resposta-cliente',
  'proposal.accepted': 'wf-06-gerar-cobranca',
  'proposal.rejected': 'wf-04-resposta-cliente',
  'payment.requested': 'wf-06-gerar-cobranca',
  'payment.confirmed': 'wf-08-liberar-servico',
  'payment.failed': 'wf-13-monitorar-erros',
  'service.completed_requested': 'wf-09-conclusao',
  'service.completed': 'wf-10-repasse',
  'dispute.created': 'wf-12-disputas',
  'dispute.resolved': 'wf-12-disputas',
  'payout.requested': 'wf-10-repasse',
  'payout.completed': 'wf-11-avaliacao',
  'payout.failed': 'wf-13-monitorar-erros',
  'review.requested': 'wf-11-avaliacao',
};
const destino = rotas[$json.event_type];
if (!destino) return { json: { ...$json, roteado: false } };
return { json: { ...$json, destino: $env.N8N_BASE_URL + '/webhook/' + destino } };
